input.content:
workspace "Sistema de Agendamento" "Agendamento de compromissos com lembretes por SMS." {

    !identifiers hierarchical

    model {
        usuarioApp = person "Usuário do app" "Usa o aplicativo mobile."
        usuarioPainel = person "Usuário do painel" "Usa o painel web."

        agendamento = softwareSystem "Sistema de Agendamento" "Gerencia agendamentos e dispara lembretes por SMS." {
            app = container "App Mobile" "Interface mobile para os agendamentos." "Flutter" "Mobile App"
            painel = container "Painel Web" "Interface web para os agendamentos." "Vue" "Web Browser"
            api = container "API" "Expõe as operações de agendamento e dispara os lembretes." "Python, FastAPI"
            db = container "Banco de Dados" "Armazena os agendamentos." "PostgreSQL 15" "Database"
        }

        twilio = softwareSystem "Twilio" "Plataforma de envio de SMS." "External"

        usuarioApp -> agendamento.app "Usa"
        usuarioPainel -> agendamento.painel "Usa"

        agendamento.app -> agendamento.api "Consulta e altera agendamentos via" "HTTPS"
        agendamento.painel -> agendamento.api "Consulta e altera agendamentos via" "HTTPS"
        agendamento.api -> agendamento.db "Lê e grava agendamentos em" "SQL"
        agendamento.api -> twilio "Envia lembretes por SMS através da" "HTTPS"
    }

    views {
        systemContext agendamento "SystemContext" {
            include *
            autoLayout
        }

        container agendamento "Containers" {
            include *
            autoLayout
        }

        styles {
            element "Person" {
                shape person
                background #08427b
                color #ffffff
            }
            element "Software System" {
                background #1168bd
                color #ffffff
            }
            element "Container" {
                background #438dd5
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Mobile App" {
                shape mobileDevicePortrait
            }
            element "Web Browser" {
                shape webBrowser
            }
            element "Database" {
                shape cylinder
            }
        }
    }

    configuration {
        scope softwaresystem
    }

}

